package main

import (
	"bufio"
	"fmt"
	"math/bits"
	"os"
	"sort"
)

const MOD int64 = 998244353
const ROOT int64 = 15311432
const INVROOT int64 = 469870224

func bitReverse(n int, k int) int {
	r := bits.Reverse32(uint32(n))
	return int(r >> uint(32-k))
}

func modPow(a int64, p int64) int64 {
	if p == 0 {
		return 1
	}
	half := modPow(a, p/2)
	ans := (half * half) % MOD
	if p%2 == 1 {
		ans = (ans * a) % MOD
	}
	return ans
}

func modInv(a int64) int64 {
	return modPow(a, MOD-2)
}

func numberTheoreticTransform(coef []int64, k int, inverse bool) {
	baseRoot := ROOT
	if inverse {
		baseRoot = INVROOT
	}
	root := modPow(baseRoot, modPow(2, int64(23-k)))
	roots := make([]int64, k)
	roots[k-1] = root
	for i := k - 1; i > 0; i-- {
		roots[i-1] = (roots[i] * roots[i]) % MOD
	}
	for s := 0; s < k; s++ {
		length := 1 << uint(s)
		for st := 0; st < len(coef); st += 2 * length {
			curRoot := int64(1)
			for j := st; j < st+length; j++ {
				t := (curRoot * coef[j+length]) % MOD
				u := coef[j]
				coef[j] = (u + t) % MOD
				coef[j+length] = (u - t) % MOD
				curRoot = (roots[s] * curRoot) % MOD
			}
		}
	}
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	var nInput int
	fmt.Fscan(reader, &nInput)
	n := nInput / 2
	var m int
	fmt.Fscan(reader, &m)
	nums := make([]int, m)
	for i := 0; i < m; i++ {
		fmt.Fscan(reader, &nums[i])
	}
	sort.Ints(nums)
	minSize := n*nums[m-1] + 2
	k := 0
	size := 1
	for size < minSize {
		size *= 2
		k++
	}
	a := make([]int64, size)
	for i := 0; i < len(nums); i++ {
		a[bitReverse(nums[i], k)] = 1
	}
	numberTheoreticTransform(a, k, false)
	for i := 0; i < size; i++ {
		a[i] = modPow(a[i], int64(n))
	}
	temp := make([]int64, size)
	for i := 0; i < size; i++ {
		temp[bitReverse(i, k)] = a[i] % MOD
	}
	a = temp
	numberTheoreticTransform(a, k, true)
	ans := int64(0)
	for i := 0; i < size; i++ {
		ans = (ans + a[i]*a[i]) % MOD
	}
	multiplier := modInv(int64(size))
	result := (((ans * multiplier) % MOD) * multiplier) % MOD
	fmt.Println(result)
}
